const COURSE_EN = {"sections":[["B2","Tes erreurs fossiles","Le -s de la 3e personne, préposition + -ing, make / do, go to, who / which"],["Pro","Factoring et onboarding","Affacturage, échéances, lancement client, appels, e-mails, chiffres"],["B2+","Sonner naturel","Phrasal verbs, small talk, réactions, réductions, storytelling"],["US","Parler comme un Américain","Slang, émotions, désaccord poli, séries, réductions, tournures natives"],["C1","Précision et nuance","Pour après le B2 : hedging, connecteurs, conditionnels, anglais de bureau, idioms"],["Perso","Sur mesure","Tes vraies erreurs et les cartes que tu rates le plus. Mis à jour à chaque « génère ».","top"]],"units":[{"e":"🔧","t":"He works, it depends : le -s","s":0,"g":{"t":"Le -s de la 3e personne","tip":"Au présent, he / she / it / un nom singulier → verbe + S : he goes, it depends, the client wants. Le -s se déplace sur l'auxiliaire dans les questions et négations : does it work? / he doesn't know (jamais deux -s).","q":[["The client ___ a weekly report.",["wants","want","is want"],0,"the client = it/he → wants"],["She ___ the deadline yet.",["doesn't know","don't know","doesn't knows"],0,"Le -s est déjà dans doesn't : verbe nu ensuite"],["___ it work on your side?",["Does","Do","Is"],0,"it → does"]]},"w":[["it depends on","ça dépend de","It depends on the client's credit limit.","Ça dépend de la limite de crédit du client.",0],["she handles","elle gère / elle s'occupe de","She handles all the onboarding calls.","Elle gère tous les appels de démarrage.",0],["he doesn't know","il ne sait pas","He doesn't know the deadline yet.","Il ne connaît pas encore l'échéance.",0],["does it work?","est-ce que ça marche ?","Does it work on your side?","Est-ce que ça marche de votre côté ?",0],["the client wants","le client veut","The client wants a weekly report.","Le client veut un rapport hebdomadaire.",0],["it takes","ça prend / il faut (durée)","It takes two days to open the account.","Il faut deux jours pour ouvrir le compte.",0],["everyone knows","tout le monde sait","Everyone knows the process by now.","Tout le monde connaît le processus maintenant.",0],["my manager says","mon manager dit","My manager says the file is complete.","Mon manager dit que le dossier est complet.",0]]},{"e":"🧩","t":"Before leaving : préposition + -ing","s":0,"g":{"t":"Préposition + verbe en -ing","tip":"Après une préposition (before, after, without, instead of, for, in, at, to dans « look forward to »), le verbe prend toujours -ING : before leaving, thanks for sending. Jamais le verbe nu, jamais « to + verbe ».","q":[["Check the figures before ___ the email.",["sending","send","to send"],0,"before + -ing"],["I look forward to ___ from you.",["hearing","hear","heard"],0,"Ici « to » est une préposition → -ing"],["She left without ___ goodbye.",["saying","say","to say"],0,"without + -ing"]]},"w":[["before leaving","avant de partir","I always check my emails before leaving the office.","Je vérifie toujours mes mails avant de quitter le bureau.",0],["after checking","après avoir vérifié","After checking the invoices, I called the client.","Après avoir vérifié les factures, j'ai appelé le client.",0],["without asking","sans demander","He changed the limit without asking anyone.","Il a modifié la limite sans demander à personne.",0],["instead of calling","au lieu d'appeler","Instead of calling, just send her a quick message.","Au lieu d'appeler, envoie-lui juste un petit message.",0],["thank you for sending","merci d'avoir envoyé","Thank you for sending the documents so quickly.","Merci d'avoir envoyé les documents aussi vite.",0],["look forward to hearing from you","dans l'attente de votre retour","I look forward to hearing from you.","Dans l'attente de votre retour.",0],["be used to working","avoir l'habitude de travailler","I'm used to working with international clients.","J'ai l'habitude de travailler avec des clients internationaux.",0],["be interested in learning","être intéressé par le fait d'apprendre","They're interested in learning more about our offer.","Ils aimeraient en savoir plus sur notre offre.",0]]},{"e":"⚖️","t":"Make ou do","s":0,"g":{"t":"Make ou do ?","tip":"MAKE = produire un résultat qui n'existait pas : make a decision, a mistake, a call, progress, money. DO = accomplir une activité ou une tâche : do business, do the paperwork, do your best, do a favor. En cas de doute : résultat → make, tâche → do.","q":[["I ___ a mistake in the report.",["made","did","done"],0,"make a mistake : on « produit » une erreur"],["We ___ business with three US banks.",["do","make","are making"],0,"do business"],["Can you ___ me a favor?",["do","make","give"],0,"do sb a favor"]]},"w":[["make a mistake","faire une erreur","I made a mistake in the last report.","J'ai fait une erreur dans le dernier rapport.",0],["make a call","passer un appel","I need to make a quick call before the meeting.","Je dois passer un appel rapide avant la réunion.",0],["make progress","progresser / avancer","We're making good progress on the onboarding.","On avance bien sur le démarrage.",0],["make an effort","faire un effort","She made a real effort to simplify the process.","Elle a vraiment fait un effort pour simplifier le processus.",0],["do business with","faire affaire avec / travailler avec","We've been doing business with them for years.","On travaille avec eux depuis des années.",0],["do sb a favor","rendre un service à qqn","Could you do me a favor and check this file?","Tu pourrais me rendre un service et vérifier ce dossier ?",0],["do your best","faire de son mieux","Just do your best, nobody expects perfection.","Fais simplement de ton mieux, personne n'attend la perfection.",0],["do the paperwork","faire la paperasse / les formalités","I still have to do the paperwork for the new client.","Je dois encore faire les formalités pour le nouveau client.",0]]},{"e":"🧭","t":"Go to, go home, get to","s":0,"g":{"t":"Go TO (jamais « go at »)","tip":"Mouvement vers un lieu = TO : go to the office, go to work, get to the station. AT = être sur place, sans mouvement : I'm at the office. Exceptions sans préposition : go home, go abroad, go there. Arrive : arrive AT (lieu précis) / IN (ville, pays), jamais « arrive to ».","q":[["I go ___ the office three days a week.",["to","at","in"],0,"Mouvement → to"],["What time did you ___ home?",["go","go to","go at"],0,"go home : sans préposition"],["We arrived ___ the station at 8.",["at","to","in the"],0,"arrive at + lieu précis"]]},"w":[["go to the office","aller au bureau","I go to the office three days a week.","Je vais au bureau trois jours par semaine.",0],["go to work","aller au travail","I usually go to work by train.","Je vais généralement au travail en train.",0],["go home","rentrer chez soi","I went home right after the meeting.","Je suis rentré juste après la réunion.",0],["get to the office","arriver au bureau","What time do you usually get to the office?","À quelle heure arrives-tu au bureau d'habitude ?",0],["go back to","retourner à","I have to go back to the office tomorrow.","Je dois retourner au bureau demain.",0],["go on a business trip","partir en déplacement professionnel","She's going on a business trip to Chicago next week.","Elle part en déplacement à Chicago la semaine prochaine.",0],["go abroad","aller à l'étranger","Most of our clients go abroad to find growth.","La plupart de nos clients vont à l'étranger pour trouver de la croissance.",0],["arrive at","arriver à (lieu précis)","We arrived at the client's office ten minutes early.","Nous sommes arrivés chez le client dix minutes en avance.",0]]},{"e":"🔗","t":"Who, which et accords","s":0,"g":{"t":"Who / which, « one of the » + pluriel, discours rapporté","tip":"WHO pour une personne, WHICH ou THAT pour une chose : the client who called, the invoice that is overdue. « One of the » + superlatif + nom PLURIEL : one of the biggest clientS. Discours rapporté : le verbe recule d'un temps (he said he WAS busy).","q":[["The person ___ handles this account is on leave.",["who","which","what"],0,"Personne → who"],["It's one of the biggest ___ in France.",["banks","bank","banking"],0,"one of the + pluriel"],["She said she ___ the file yesterday.",["had sent","sends","has send"],0,"said → le temps recule"]]},"w":[["the client who called","le client qui a appelé","The client who called this morning wants a higher limit.","Le client qui a appelé ce matin veut une limite plus élevée.",0],["the invoice that is overdue","la facture qui est en retard","Can you send me the invoice that is overdue?","Peux-tu m'envoyer la facture qui est en retard ?",0],["one of the biggest clients","l'un des plus gros clients","They're one of the biggest clients in our portfolio.","C'est l'un des plus gros clients de notre portefeuille.",0],["one of the best players","l'un des meilleurs joueurs","He's one of the best players in the league.","C'est l'un des meilleurs joueurs du championnat.",0],["he said he was busy","il a dit qu'il était occupé","He said he was busy, so I'll call back tomorrow.","Il a dit qu'il était occupé, donc je rappellerai demain.",0],["she told me that","elle m'a dit que","She told me that the contract was signed.","Elle m'a dit que le contrat était signé.",0],["the report that I sent","le rapport que j'ai envoyé","Did you read the report that I sent on Monday?","As-tu lu le rapport que j'ai envoyé lundi ?",0],["the person who handles","la personne qui s'occupe de","I'll put you in touch with the person who handles your account.","Je vous mets en contact avec la personne qui gère votre compte.",0]]},{"e":"🏦","t":"Les bases du factoring","s":1,"free":true,"g":{"t":"Faux-amis de la finance","tip":"Une facture = an invoice (« a facture » n'existe pas ; « a bill » = l'addition, la facture d'un particulier). Une créance = a receivable. Le débiteur = the debtor (le B est muet : « DÈ-teur »). Céder = to assign, pas « to cede ».","q":[["We purchase the client's ___.",["receivables","creances","credits"],0,"créances = receivables"],["The ___ has 60 days to pay the invoice.",["debtor","debitor","debiter"],0,"debtor, B muet"],["Please send us the ___ for March.",["invoices","factures","notes"],0,"facture = invoice"]]},"w":[["factoring","l'affacturage","Factoring turns unpaid invoices into immediate cash.","L'affacturage transforme les factures impayées en trésorerie immédiate.",0],["accounts receivable","les créances clients / le poste clients","Their accounts receivable doubled in two years.","Leur poste clients a doublé en deux ans.",0],["an invoice","une facture","The invoice is due in thirty days.","La facture est exigible dans trente jours.",0],["a debtor","un débiteur (le client de votre client)","We check every debtor before setting a limit.","Nous vérifions chaque débiteur avant de fixer une limite.",0],["to assign receivables","céder des créances","The client assigns its receivables to the factor.","Le client cède ses créances au factor.",0],["a credit limit","une limite de crédit / un plafond","We set a credit limit for each debtor.","Nous fixons une limite de crédit pour chaque débiteur.",0],["funding","le financement","Funding is available the day after the invoice is uploaded.","Le financement est disponible le lendemain du dépôt de la facture.",0],["confidential factoring","l'affacturage confidentiel","With confidential factoring, the debtors are not notified.","En affacturage confidentiel, les débiteurs ne sont pas notifiés.",0]]},{"e":"⏰","t":"Échéances et recouvrement","s":1,"free":true,"g":{"t":"Due, overdue, outstanding","tip":"DUE = exigible à une date (due on May 3, due in 30 days). OVERDUE = en retard, échéance dépassée. OUTSTANDING = encore à payer, pas forcément en retard (attention : « an outstanding result » = un résultat remarquable).","q":[["The invoice is 15 days ___.",["overdue","late of","in retard"],0,"échéance dépassée = overdue"],["Payment is due ___ thirty days.",["in","at","on"],0,"due in + durée, due on + date"],["What's the ___ balance on this account?",["outstanding","rest","staying"],0,"encours restant dû = outstanding balance"]]},"w":[["overdue","en retard (de paiement) / échu impayé","Three invoices are more than 30 days overdue.","Trois factures ont plus de 30 jours de retard.",0],["the due date","la date d'échéance","The due date is printed at the top of the invoice.","La date d'échéance est imprimée en haut de la facture.",0],["payment terms","les conditions / délais de paiement","Their payment terms are net sixty days.","Leurs délais de paiement sont de soixante jours nets.",0],["outstanding balance","l'encours / le solde restant dû","The outstanding balance is just under two million euros.","L'encours est d'un peu moins de deux millions d'euros.",0],["collection","le recouvrement","Collection stays with the client in a confidential program.","Le recouvrement reste chez le client dans un programme confidentiel.",0],["a dispute","un litige","The debtor raised a dispute on two invoices.","Le débiteur a ouvert un litige sur deux factures.",0],["a credit note","un avoir","We issued a credit note for the damaged goods.","Nous avons émis un avoir pour la marchandise abîmée.",0],["to default on","faire défaut sur / ne pas honorer","The debtor defaulted on its payments last quarter.","Le débiteur a fait défaut sur ses paiements au dernier trimestre.",0]]},{"e":"🚀","t":"Lancer un client (onboarding)","s":1,"free":true,"g":{"t":"Walk through, set up, sign off","tip":"Trois phrasal verbs du démarrage. Walk SOMEONE through = expliquer pas à pas (la personne au milieu). Set up = mettre en place (set it up). Sign off ON = valider formellement. Le démarrage = onboarding ; la mise en production = go-live.","q":[["Let me walk ___ the process.",["you through","through you","you to"],0,"walk sb through sth"],["The account is ready. We ___ yesterday.",["set it up","set up it","setted it up"],0,"Pronom au milieu ; set est irrégulier (set, set, set)"],["Legal still has to sign off ___ the contract.",["on","of","to"],0,"sign off ON"]]},"w":[["onboarding","le démarrage / la mise en place d'un client","Onboarding usually takes four to six weeks.","Le démarrage prend généralement quatre à six semaines.",0],["a kickoff call","un appel de lancement","Let's schedule the kickoff call for next Tuesday.","Planifions l'appel de lancement pour mardi prochain.",0],["to set up","mettre en place / configurer","We'll set up your account by the end of the week.","Nous mettrons en place votre compte d'ici la fin de la semaine.",0],["go-live","la mise en production / le démarrage effectif","Go-live is planned for the first of December.","La mise en production est prévue pour le premier décembre.",0],["a milestone","un jalon / une étape clé","The first data upload is a key milestone.","Le premier dépôt de données est un jalon clé.",0],["to walk sb through","expliquer qqch pas à pas à qqn","I'll walk you through the reporting tool.","Je vais vous expliquer l'outil de reporting pas à pas.",0],["requirements","les exigences / les besoins / les prérequis","Could you send us your technical requirements?","Pourriez-vous nous envoyer vos prérequis techniques ?",0],["to sign off on","valider formellement / donner son feu vert à","Compliance has to sign off on the contract first.","La conformité doit d'abord valider le contrat.",0]]},{"e":"📞","t":"Appels et réunions","s":1,"free":true,"g":{"t":"Sonner naturel en call","tip":"Formules US de tous les jours : « on my end » (de mon côté), « I'll get back to you » (je reviens vers vous), « you're on mute » (votre micro est coupé), « let me share my screen ». Évite les calques : « I come back to you », « from my side » à répétition, « I'm agree ».","q":[["I'll check and get back ___ you tomorrow.",["to","at","on"],0,"get back TO sb"],["Everything looks good ___ my end.",["on","in","at"],0,"on my end"],["Sorry, I ___ with you on this point.",["agree","am agree","am agreeing"],0,"agree est un verbe : I agree"]]},"w":[["to schedule a call","planifier un appel","Can we schedule a call for Thursday afternoon?","Peut-on planifier un appel pour jeudi après-midi ?",0],["to follow up","relancer / faire le suivi","I'll follow up with the bank tomorrow morning.","Je relancerai la banque demain matin.",0],["to get back to sb","revenir vers qqn / recontacter","Let me check with IT and get back to you.","Je vérifie avec l'informatique et je reviens vers vous.",0],["on my end","de mon côté","Everything is ready on my end.","Tout est prêt de mon côté.",0],["to run late","être en retard","Sorry, I'm running a few minutes late.","Désolé, j'ai quelques minutes de retard.",0],["to share my screen","partager mon écran","Let me share my screen so you can see the report.","Je partage mon écran pour que vous voyiez le rapport.",0],["to be on mute","avoir le micro coupé","I think you're on mute, we can't hear you.","Je crois que votre micro est coupé, on ne vous entend pas.",0],["next steps","les prochaines étapes","Let's wrap up with the next steps.","Terminons par les prochaines étapes.",0]]},{"e":"✉️","t":"E-mails pro","s":1,"free":true,"g":{"t":"Formules d'e-mail","tip":"Ouvrir : « I'm reaching out regarding… » ou « Following up on our call… ». Joindre : « Please find attached… » (ou « I've attached… », plus moderne). Demander : « Could you confirm…? ». Fermer : « Let me know if you have any questions » puis « Best regards, ». Pas de « I send you », pas de « informations ».","q":[["Please find ___ the signed contract.",["attached","joined","enclosed to"],0,"pièce jointe = attached"],["Thank you for the ___.",["information","informations","informationes"],0,"information est indénombrable"],["I'm reaching out ___ the onboarding schedule.",["regarding","for regard","on regard of"],0,"regarding = au sujet de"]]},"w":[["please find attached","veuillez trouver ci-joint","Please find attached the onboarding schedule.","Veuillez trouver ci-joint le planning de démarrage.",0],["I'm reaching out to","je vous contacte pour","I'm reaching out to confirm the kickoff date.","Je vous contacte pour confirmer la date de lancement.",0],["as discussed","comme convenu / comme évoqué","As discussed, here is the updated timeline.","Comme convenu, voici le calendrier mis à jour.",0],["could you confirm","pourriez-vous confirmer","Could you confirm the go-live date by Friday?","Pourriez-vous confirmer la date de mise en production d'ici vendredi ?",0],["at your earliest convenience","dès que possible (poli)","Please send the signed copy at your earliest convenience.","Merci d'envoyer l'exemplaire signé dès que possible.",0],["let me know if","dites-moi si / n'hésitez pas si","Let me know if you have any questions.","N'hésitez pas si vous avez des questions.",0],["I'll keep you posted","je vous tiens au courant","I'll keep you posted on the bank's answer.","Je vous tiens au courant de la réponse de la banque.",0],["thanks in advance","merci d'avance","Thanks in advance for your help.","Merci d'avance pour votre aide.",0]]},{"e":"📊","t":"Chiffres et reporting","s":1,"free":true,"g":{"t":"Dire les chiffres","tip":"Point pour les décimales, virgule pour les milliers : 1.5 million, 2,300 invoices. Pas de -s à million / thousand après un nombre : two million euros. Increase BY 10% = de 10 % (l'écart). Increase TO 10% = jusqu'à 10 % (le niveau atteint). Chiffre d'affaires = revenue (US), turnover (UK).","q":[["Revenue rose ___ 12% last year.",["by","of","to the"],0,"L'écart → by"],["The limit is two ___ euros.",["million","millions","millions of"],0,"Pas de -s après un nombre"],["How do you say 3,5 % in English?",["three point five percent","three comma five percent","three and five percent"],0,"Décimale = point"]]},"w":[["revenue","le chiffre d'affaires","Their revenue grew by twelve percent last year.","Leur chiffre d'affaires a augmenté de douze pour cent l'an dernier.",0],["an aging report","une balance âgée","The aging report shows what is overdue by more than 60 days.","La balance âgée montre ce qui est en retard de plus de 60 jours.",0],["a breakdown","une ventilation / un détail","Could you send a breakdown by debtor?","Pourriez-vous envoyer une ventilation par débiteur ?",0],["to increase by","augmenter de","Outstandings increased by ten percent in March.","L'encours a augmenté de dix pour cent en mars.",0],["figures","les chiffres","I'll send you the final figures on Monday.","Je vous envoie les chiffres définitifs lundi.",0],["year-over-year","sur un an / en glissement annuel","Revenue is up eight percent year-over-year.","Le chiffre d'affaires est en hausse de huit pour cent sur un an.",0],["a shortfall","un manque / un déficit (par rapport à l'attendu)","There's a shortfall of fifty thousand euros this month.","Il y a un manque de cinquante mille euros ce mois-ci.",0],["roughly","environ / à peu près","We fund roughly eighty percent of each invoice.","Nous finançons environ quatre-vingts pour cent de chaque facture.",0]]},{"e":"🧱","t":"Phrasal verbs du quotidien","s":2,"g":{"t":"Séparable ou pas ?","tip":"Certains phrasal verbs se coupent avec un pronom : bring it up, figure it out. D'autres jamais : run into him, look into it.","q":[["I need to ___ before Monday.",["figure it out","figure out it","it figure out"],0,"Pronom au milieu : figure it out"],["I ___ at the gym yesterday.",["ran into him","ran him into","into him ran"],0,"run into est inséparable"]]},"w":[["figure out","comprendre / trouver la solution","I still can't figure out why the query is so slow.","Je n'arrive toujours pas à comprendre pourquoi la requête est si lente.",0],["come up with","trouver (une idée)","She came up with a brilliant workaround.","Elle a trouvé une solution de contournement géniale.",0],["run into","tomber sur (qqn)","I ran into my old manager at the airport.","Je suis tombé sur mon ancien manager à l'aéroport.",0],["put off","repousser / remettre à plus tard","Stop putting off the hard conversations.","Arrête de repousser les conversations difficiles.",0],["get over","se remettre de","It took me months to get over that breakup.","J'ai mis des mois à me remettre de cette rupture.",0],["look into","se pencher sur / examiner","I'll look into it and get back to you.","Je vais regarder ça et je reviens vers toi.",0],["bring up","aborder (un sujet)","Don't bring up politics at dinner.","N'aborde pas la politique au dîner.",0],["end up","finir par","We ended up staying until 2 a.m.","On a fini par rester jusqu'à 2 h du matin.",0]]},{"e":"☕","t":"Small talk à l'américaine","s":2,"g":{"t":"Le present perfect continu","tip":"« What have you been up to? » = qu'est-ce que tu deviens ? Action commencée dans le passé et toujours en cours.","q":[["What ___ up to lately?",["have you been","did you","are you been"],0,"have + been + -ing / up to"],["I ___ a lot lately.",["have been traveling","traveled since","am traveling since"],0,"lately → present perfect"]]},"w":[["How's it going?","Comment ça va ?","Hey man, how's it going?","Salut mec, comment ça va ?",0],["What have you been up to?","Qu'est-ce que tu deviens ?","Long time no see! What have you been up to?","Ça fait longtemps ! Qu'est-ce que tu deviens ?",0],["Not much, you?","Pas grand-chose, et toi ?","Not much, you? Still at EY?","Pas grand-chose, et toi ? Toujours chez EY ?",0],["I hear you","je te comprends","I hear you, Mondays are brutal.","Je te comprends, les lundis sont durs.",0],["Fair enough","c'est de bonne guerre / OK, ça se tient","Fair enough, let's do it your way.","OK, ça se tient, faisons comme tu dis.",0],["No worries","pas de souci","No worries, take your time.","Pas de souci, prends ton temps.",0],["Sounds good","ça marche","Lunch at noon? — Sounds good.","Déjeuner à midi ? — Ça marche.",0],["Catch you later","à plus","Gotta run, catch you later!","Je dois filer, à plus !",0]]},{"e":"💬","t":"Réactions et fillers","s":2,"g":{"t":"« kind of » pour nuancer","tip":"« kind of / kinda » adoucit un adjectif ou un verbe : I'm kinda tired. It kind of makes sense.","q":[["Le plus naturel :",["I'm kinda tired.","I'm tired kind.","I kind am tired."],0,"kind of se place devant l'adjectif"],["Pour réagir à une nouvelle incroyable :",["No way!","Not way!","No how!"],0,"No way! = sans blague !"]]},"w":[["I mean","enfin / je veux dire","I mean, it's not perfect, but it works.","Enfin, c'est pas parfait, mais ça marche.",0],["you know","tu vois","It's just, you know, a lot of pressure.","C'est juste, tu vois, beaucoup de pression.",0],["kind of","un peu / plutôt","I'm kind of nervous about the interview.","Je suis un peu nerveux pour l'entretien.",0],["honestly","franchement","Honestly, I didn't see that coming.","Franchement, je ne l'ai pas vu venir.",0],["For real?","Sérieux ?","You quit your job? For real?","Tu as démissionné ? Sérieux ?",0],["No way!","Sans blague ! / Pas possible !","No way! You met her in Madrid?","Sans blague ! Tu l'as rencontrée à Madrid ?",0],["That makes sense","c'est logique","Oh, that makes sense now.","Ah, c'est logique maintenant.",0],["Totally","carrément / complètement","I totally forgot about the meeting.","J'ai complètement oublié la réunion.",0]]},{"e":"🗣️","t":"Gonna, wanna, gotta","s":2,"g":{"t":"« gonna » ≠ aller quelque part","tip":"gonna = going to + VERBE (I'm gonna call). Jamais pour un lieu : I'm going to Paris (pas « gonna Paris »).","q":[["Lequel est correct ?",["I'm gonna call you.","I'm gonna Paris.","I gonna call you."],0,"gonna + verbe, avec be"],["« I've got to go » à l'oral :",["I gotta go.","I gonna go.","I wanna go."],0,"got to → gotta"]]},"w":[["gonna","going to (futur)","I'm gonna grab a coffee, want one?","Je vais prendre un café, t'en veux un ?",0],["wanna","want to","Do you wanna come with us?","Tu veux venir avec nous ?",0],["gotta","have got to / doit","I gotta finish this deck tonight.","Je dois finir ce deck ce soir.",0],["lemme","let me","Lemme check my calendar.","Laisse-moi vérifier mon agenda.",0],["gimme","give me","Gimme a sec.","Donne-moi une seconde.",0],["dunno","don't know","I dunno, man, it's up to you.","Je sais pas, mec, c'est toi qui vois.",0],["kinda","kind of","It's kinda late, let's head out.","Il est un peu tard, on y va.",0],["whatcha","what are you / what do you","Whatcha doing this weekend?","Tu fais quoi ce week-end ?",0]]},{"e":"📖","t":"Raconter une histoire","s":2,"g":{"t":"Prétérit continu = décor","tip":"Le past continuous plante le décor, le simple past fait avancer l'action : I was walking home when it started to rain.","q":[["I ___ when my phone rang.",["was cooking","cooked","am cooking"],0,"décor en cours → was cooking"],["While we were talking, she suddenly ___.",["left","was leaving","leaves"],0,"action ponctuelle → simple past"]]},"w":[["So get this","Écoute ça / Tiens-toi bien","So get this: he showed up two hours late.","Écoute ça : il s'est pointé avec deux heures de retard.",0],["out of nowhere","sorti de nulle part","Out of nowhere, a guy starts yelling.","Sorti de nulle part, un mec se met à crier.",0],["all of a sudden","tout à coup","All of a sudden the lights went out.","Tout à coup, les lumières se sont éteintes.",0],["turns out","en fait / il s'avère que","Turns out she was his sister.","En fait, c'était sa sœur.",0],["long story short","pour faire court","Long story short, we missed the flight.","Pour faire court, on a raté l'avion.",0],["I was like","je me suis dit / j'ai fait","I was like, “are you serious?”","Je me suis dit : « t'es sérieux ? »",0],["next thing I know","et là, d'un coup","Next thing I know, I'm on stage.","Et là, d'un coup, je me retrouve sur scène.",0],["to top it off","pour couronner le tout","To top it off, it started raining.","Pour couronner le tout, il s'est mis à pleuvoir.",0]]},{"e":"🧭","t":"Collocations clés","s":2,"g":{"t":"Make ou do ?","tip":"make = créer, produire (make a decision, make sense) ; do = activité, tâche (do research, do the dishes).","q":[["We need to ___ a decision today.",["make","do","take"],0,"make a decision"],["I'll ___ some research first.",["do","make","have"],0,"do research"]]},"w":[["make a decision","prendre une décision","We have to make a decision by Friday.","On doit prendre une décision d'ici vendredi.",0],["take a break","faire une pause","Let's take a five-minute break.","Faisons une pause de cinq minutes.",0],["pay attention","faire attention","Pay attention to the edge cases.","Fais attention aux cas limites.",0],["have a point","ne pas avoir tort","You have a point, I hadn't thought of that.","Tu n'as pas tort, je n'y avais pas pensé.",0],["do research","faire des recherches","I did some research before the call.","J'ai fait des recherches avant l'appel.",0],["make sense","avoir du sens","Does that make sense?","Est-ce que c'est clair ?",0],["take into account","prendre en compte","We need to take seasonality into account.","Il faut prendre en compte la saisonnalité.",0],["raise a question","soulever une question","That raises a good question.","Ça soulève une bonne question.",0]]},{"e":"🔥","t":"Slang US","s":3,"g":{"t":"Position de « low-key »","tip":"low-key se place devant ce qu'il nuance : I low-key want to leave. = discrètement, un peu.","q":[["Le plus naturel :",["I low-key miss him.","I miss low-key him.","Low-key I him miss."],0,"low-key devant le verbe"],["« No cap » veut dire…",["sans mentir","pas de chapeau","sans limite"],0,"no cap = for real"]]},"w":[["low-key","discrètement / un peu","I low-key want to skip the party.","J'ai un peu envie de sécher la soirée.",0],["high-key","clairement / carrément","I high-key love this song.","J'adore carrément cette chanson.",0],["no cap","sans mentir","That was the best burger ever, no cap.","C'était le meilleur burger de ma vie, sans mentir.",0],["salty","vexé / aigri","He's still salty about losing.","Il est encore vexé d'avoir perdu.",0],["to ghost","disparaître sans prévenir","She ghosted me after the second date.","Elle a disparu après le deuxième rendez-vous.",0],["to flex","frimer","He's always flexing his new car.","Il frime tout le temps avec sa nouvelle voiture.",0],["sus","louche","That email looks sus.","Ce mail a l'air louche.",0],["Bet.","Ça marche. / Ok.","See you at 8? — Bet.","On se voit à 8 h ? — Ça marche.",0]]},{"e":"😤","t":"Exprimer ses émotions","s":3,"g":{"t":"-ed ou -ing ?","tip":"-ed = ce que je ressens (I'm bored) ; -ing = ce qui provoque (it's boring).","q":[["The movie was so ___.",["boring","bored","bore"],0,"le film provoque l'ennui → -ing"],["I'm ___ about the trip!",["pumped","pumping","pump"],0,"ce que je ressens → -ed"]]},"w":[["I'm bummed","je suis dégoûté / déçu","I'm bummed I missed the concert.","Je suis dégoûté d'avoir raté le concert.",0],["I'm stoked","je suis trop content","I'm stoked about the new job!","Je suis trop content pour le nouveau job !",0],["it drives me nuts","ça me rend dingue","His typing drives me nuts.","Sa façon de taper me rend dingue.",0],["I'm freaking out","je panique","I'm freaking out about the presentation.","Je panique pour la présentation.",0],["I'm over it","j'en ai ma claque / je suis passé à autre chose","Honestly, I'm over it.","Franchement, je suis passé à autre chose.",0],["it got to me","ça m'a touché / atteint","I tried to ignore it, but it got to me.","J'ai essayé d'ignorer, mais ça m'a atteint.",0],["I can't stand","je ne supporte pas","I can't stand people who chew loudly.","Je ne supporte pas les gens qui mâchent fort.",0],["I'm pumped","je suis surexcité","I'm pumped for the game tonight!","Je suis surexcité pour le match ce soir !",0]]},{"e":"🤝","t":"Être en désaccord poliment","s":3,"g":{"t":"« I'd » = I would","tip":"I'd push back on that / I'd disagree = forme polie et naturelle pour contredire.","q":[["Version la plus polie :",["I'd push back on that a little.","You're wrong.","That's stupid."],0,"I'd + verbe adoucit"],["« Je vois d'où tu viens, mais… » =",["I see where you're coming from, but…","I see from where you come, but…","I watch where you come, but…"],0,"expression figée"]]},"w":[["I see where you're coming from","je comprends ton point de vue","I see where you're coming from, but the data says otherwise.","Je comprends ton point de vue, mais les données disent le contraire.",0],["I'm not sure I'd go that far","je n'irais pas jusque-là","Disaster? I'm not sure I'd go that far.","Une catastrophe ? Je n'irais pas jusque-là.",0],["Fair point, however","bon point, cependant","Fair point, however we can't ignore the cost.","Bon point, cependant on ne peut pas ignorer le coût.",0],["I'd push back on that","je ne suis pas d'accord là-dessus","I'd push back on that a little.","Je ne suis pas tout à fait d'accord là-dessus.",0],["That's one way to look at it","c'est une façon de voir","That's one way to look at it, sure.","C'est une façon de voir, oui.",0],["Let's agree to disagree","restons-en à nos désaccords","OK, let's agree to disagree.","OK, chacun garde son avis.",0],["With all due respect","sauf votre respect","With all due respect, that's not what we agreed on.","Sauf votre respect, ce n'est pas ce qu'on avait convenu.",0],["I hear you, but","je t'entends, mais","I hear you, but we can't push the deadline.","Je t'entends, mais on ne peut pas repousser la deadline.",0]]},{"e":"🎬","t":"Répliques de séries","s":3,"g":{"t":"« have got » à l'oral US","tip":"I've got your back = I have your back. À l'oral on réduit : I got you / I got your back.","q":[["« Je te couvre » =",["I've got your back.","I have your back on.","I got back you."],0,"have got sb's back"],["« C'est ma faute » (oral) :",["My bad.","My fault bad.","Bad mine."],0,"My bad = oups, ma faute"]]},"w":[["What's up with that?","C'est quoi ce délire ?","He left without paying? What's up with that?","Il est parti sans payer ? C'est quoi ce délire ?",0],["You've got to be kidding me","Tu te fiches de moi","Another meeting? You've got to be kidding me.","Encore une réunion ? Tu te fiches de moi.",0],["I'm all ears","je suis tout ouïe","Go ahead, I'm all ears.","Vas-y, je suis tout ouïe.",0],["That's on me","c'est de ma faute","The delay? That's on me.","Le retard ? C'est de ma faute.",0],["My bad","oups, ma faute","My bad, I sent the wrong file.","Oups, j'ai envoyé le mauvais fichier.",0],["I've got your back","je te couvre","Don't worry, I've got your back.","T'inquiète, je te couvre.",0],["Get out of here!","Sans déconner !","You got promoted? Get out of here!","T'as été promu ? Sans déconner !",0],["Spill the tea","balance les potins","OK, spill the tea, what happened?","OK, balance, il s'est passé quoi ?",0]]},{"e":"🎵","t":"Réductions avancées","s":3,"g":{"t":"shoulda / coulda / woulda","tip":"should have + PP → shoulda + PP : I shoulda known. Jamais « should of ».","q":[["« I should have known » à l'oral :",["I shoulda known.","I should of known.","I shoulda know."],0,"shoulda + participe passé"],["« Did you eat? » à l'oral :",["Didja eat?","Dija eaten?","Did ya ate?"],0,"did you → didja"]]},"w":[["shoulda","should have","I shoulda left earlier.","J'aurais dû partir plus tôt.",0],["coulda","could have","It coulda been worse.","Ça aurait pu être pire.",0],["woulda","would have","I woulda called if I'd known.","J'aurais appelé si j'avais su.",0],["didja","did you","Didja see the game last night?","T'as vu le match hier soir ?",0],["whaddaya","what do you","Whaddaya think?","T'en penses quoi ?",0],["gotcha","got you / compris","Gotcha, I'll send it now.","Compris, je l'envoie maintenant.",0],["outta","out of","I'm outta here.","Je me casse.",0],["hafta","have to","I hafta wake up at six.","Je dois me lever à six heures.",0]]},{"e":"🏆","t":"Tournures natives","s":3,"g":{"t":"« I'm good » = non merci","tip":"Aux US, « I'm good » répond souvent à une offre : Want some more? — I'm good, thanks. (= non merci)","q":[["Want another drink? — ___",["I'm good, thanks.","I'm well, thanks.","I'm fine of it."],0,"I'm good = non merci"],["« C'est comme ça » =",["It is what it is.","It is how it is.","It's like that it is."],0,"expression figée"]]},"w":[["I'm down","je suis partant","Tacos tonight? — I'm down.","Tacos ce soir ? — Je suis partant.",0],["It's not my thing","ce n'est pas mon truc","Karaoke's not really my thing.","Le karaoké, c'est pas trop mon truc.",0],["I'm good","non merci / ça va","More coffee? — I'm good, thanks.","Encore du café ? — Non merci, ça va.",0],["You do you","fais comme tu le sens","You wanna quit? You do you.","Tu veux arrêter ? Fais comme tu le sens.",0],["That's a wrap","c'est fini / c'est bouclé","OK everyone, that's a wrap!","OK tout le monde, c'est bouclé !",0],["It is what it is","c'est comme ça","We lost, it is what it is.","On a perdu, c'est comme ça.",0],["Let's call it a day","on s'arrête là pour aujourd'hui","It's 8 p.m., let's call it a day.","Il est 20 h, on s'arrête là.",0],["I'll pass","je passe mon tour","Skydiving? I'll pass.","Du saut en parachute ? Je passe mon tour.",0]]},{"e":"🫠","t":"Mots du quotidien US","s":3,"g":{"t":"Verbes expressifs : onomatopées en action","tip":"L'anglais oral US adore les verbes très visuels/sonores : to slop (renverser salement), jiggling (qui tremble/gigote). Ils peignent la scène.","q":[["Don't ___ the soup everywhere!",["slop","slap","slip"],0,"slop = renverser salement"],["Stop ___ the table, you're spilling my drink.",["jiggling","giggling","juggling"],0,"jiggling = secouer/faire trembler"]]},"w":[["to slop","Renverser salement / Éclabousser (fam.)","He slopped coffee all over his shirt.","Il a renversé du café partout sur sa chemise.",0],["jiggling","Qui gigote / Qui tremble / Qui secoue","The kid kept jiggling his leg under the desk.","Le gamin n'arrêtait pas de faire trembler sa jambe sous le bureau.",0]]},{"e":"🤏","t":"Nuancer (hedging)","s":4,"g":{"t":"« would » pour adoucir","tip":"Un natif C1 adoucit ses affirmations : I'd say… / I would argue… / It would seem that…","q":[["Version la plus nuancée :",["I'd say it's a bit risky.","It is risky.","It's risky, period."],0,"I'd say = adoucisseur"],["« Dans une certaine mesure » =",["to some extent","to some measure","in a certain measure"],0,"to some extent"]]},"w":[["I'd say","je dirais","I'd say we're about 80% done.","Je dirais qu'on a fini à 80 %.",0],["it seems to me","il me semble","It seems to me that the scope keeps changing.","Il me semble que le périmètre change sans arrêt.",0],["arguably","sans doute / on peut dire que","It's arguably the best pizza in town.","C'est sans doute la meilleure pizza de la ville.",0],["to some extent","dans une certaine mesure","I agree, to some extent.","Je suis d'accord, dans une certaine mesure.",0],["I could be wrong, but","je me trompe peut-être, mais","I could be wrong, but I think the numbers are off.","Je me trompe peut-être, mais je pense que les chiffres sont faux.",0],["more or less","plus ou moins","It's more or less what we expected.","C'est plus ou moins ce qu'on attendait.",0],["tends to","a tendance à","He tends to overthink everything.","Il a tendance à trop réfléchir.",0],["it's not that…, it's just that","ce n'est pas que…, c'est juste que","It's not that I don't like it, it's just that it's expensive.","Ce n'est pas que je n'aime pas, c'est juste que c'est cher.",0]]},{"e":"🔀","t":"Connecteurs C1","s":4,"g":{"t":"whereas / while / although","tip":"whereas oppose deux faits ; although = bien que ; while fait les deux mais est plus oral.","q":[["I love cities, ___ my wife prefers the countryside.",["whereas","although","despite"],0,"opposition de deux faits → whereas"],["___ it was raining, we went out.",["Although","Whereas","Despite"],0,"concession → although"]]},"w":[["that said","cela dit","That said, I see your point.","Cela dit, je comprends ton point de vue.",0],["even so","quand bien même / malgré tout","It's risky. Even so, I think we should try.","C'est risqué. Malgré tout, je pense qu'on devrait essayer.",0],["whereas","alors que","He's outgoing, whereas his brother is shy.","Il est extraverti, alors que son frère est timide.",0],["given that","étant donné que","Given that we're short on time, let's skip the intro.","Étant donné qu'on manque de temps, sautons l'intro.",0],["as long as","tant que","You can stay as long as you're quiet.","Tu peux rester tant que tu restes calme.",0],["provided that","à condition que","I'll sign, provided that they fix the clause.","Je signerai, à condition qu'ils corrigent la clause.",0],["on top of that","en plus de ça","On top of that, the client changed the deadline.","En plus de ça, le client a changé la deadline.",0],["by and large","dans l'ensemble","By and large, the project went well.","Dans l'ensemble, le projet s'est bien passé.",0]]},{"e":"🌀","t":"Conditionnels et regrets","s":4,"g":{"t":"Le conditionnel mixte","tip":"Passé → conséquence présente : If I had studied harder, I would be a doctor now.","q":[["If I ___ the offer, I'd be living in NYC now.",["had taken","took","would take"],0,"condition passée → had + PP"],["___ I known, I would have called.",["Had","If had","Would"],0,"inversion : Had I known = If I had known"]]},"w":[["If I had known","si j'avais su","If I had known, I wouldn't have come.","Si j'avais su, je ne serais pas venu.",0],["I wish I had","je regrette de ne pas avoir","I wish I had learned Spanish as a kid.","J'aurais aimé apprendre l'espagnol enfant.",0],["If only","si seulement","If only I'd listened to you.","Si seulement je t'avais écouté.",0],["Had I known","si j'avais su (soutenu)","Had I known, I'd have booked earlier.","Si j'avais su, j'aurais réservé plus tôt.",0],["Suppose","imagine que","Suppose they say no, what's plan B?","Imagine qu'ils disent non, c'est quoi le plan B ?",0],["otherwise","sinon","Leave now, otherwise you'll miss the train.","Pars maintenant, sinon tu vas rater le train.",0],["I'd rather you didn't","je préférerais que tu ne le fasses pas","I'd rather you didn't tell him yet.","Je préférerais que tu ne lui dises pas encore.",0],["It's high time","il est grand temps","It's high time we talked about it.","Il est grand temps qu'on en parle.",0]]},{"e":"💼","t":"Anglais pro (consulting)","s":4,"g":{"t":"Prépositions des phrasal verbs pro","tip":"circle back ON a topic · touch base WITH someone · loop someone IN · push back ON something.","q":[["Let's circle back ___ this next week.",["on","to","at"],0,"circle back on"],["I'll loop you ___ on the thread.",["in","on","at"],0,"loop sb in"]]},"w":[["circle back","revenir sur un sujet","Let's circle back on the budget tomorrow.","Revenons sur le budget demain.",0],["touch base","faire un point rapide","Let's touch base after the client call.","Faisons un point après l'appel client.",0],["bandwidth","disponibilité / capacité","I don't have the bandwidth this week.","Je n'ai pas la dispo cette semaine.",0],["low-hanging fruit","gains rapides / quick wins","Let's start with the low-hanging fruit.","Commençons par les quick wins.",0],["deliverable","livrable","The main deliverable is due Friday.","Le livrable principal est pour vendredi.",0],["loop in","mettre dans la boucle","I'll loop in the data team.","Je mets l'équipe data dans la boucle.",0],["push back","résister / contester","Don't be afraid to push back on the client.","N'aie pas peur de challenger le client.",0],["ballpark figure","ordre de grandeur","Can you give me a ballpark figure?","Tu peux me donner un ordre de grandeur ?",0]]},{"e":"🎯","t":"Idioms C1","s":4,"g":{"t":"Les idioms se conjuguent","tip":"Le verbe de l'idiom se conjugue normalement : He cut corners. She's been beating around the bush.","q":[["He always ___ corners.",["cuts","cut it","cutting"],0,"il → cuts"],["Stop ___ around the bush!",["beating","beat","to beat"],0,"Stop + -ing"]]},"w":[["hit the nail on the head","mettre le doigt dessus","You hit the nail on the head.","Tu as mis le doigt dessus.",0],["cut corners","bâcler / rogner sur la qualité","They cut corners and it shows.","Ils ont bâclé et ça se voit.",0],["the ball is in your court","la balle est dans ton camp","I sent the offer, the ball is in your court.","J'ai envoyé l'offre, la balle est dans ton camp.",0],["on the fence","indécis","I'm still on the fence about moving.","J'hésite encore à déménager.",0],["a blessing in disguise","un mal pour un bien","Losing that job was a blessing in disguise.","Perdre ce job a été un mal pour un bien.",0],["beat around the bush","tourner autour du pot","Stop beating around the bush.","Arrête de tourner autour du pot.",0],["get the hang of it","prendre le coup de main","You'll get the hang of it.","Tu vas prendre le coup de main.",0],["play it by ear","improviser / voir sur le moment","Let's play it by ear tonight.","On verra sur le moment ce soir.",0]]},{"e":"🧩","t":"Adverbial phrases — Opinion","s":4,"g":{"t":"Placement en début de phrase","tip":"Les adverbial phrases d'opinion se placent en tête pour cadrer tout ce qui suit : As far as I'm concerned, … / If anything, … / For what it's worth, …","q":[["___, we should cancel the project.",["As far as I'm concerned","As far as I concern","As far I'm concerned"],0,"as far as I'm concerned = en ce qui me concerne"],["___, the new design is actually worse.",["If anything","If something","If ever"],0,"if anything = au contraire, ce serait plutôt… (on corrige ce qui vient d'être dit)"]]},"w":[["as far as I'm concerned","en ce qui me concerne","As far as I'm concerned, we're done here.","En ce qui me concerne, on a fini.",0],["if anything","au contraire / ce serait plutôt l'inverse","It didn't fix the bug. If anything, the update made it slower.","Ça n'a pas corrigé le bug. Au contraire, la mise à jour a plutôt ralenti les choses.",0],["for what it's worth","pour ce que ça vaut","For what it's worth, I think you're making the right call.","Pour ce que ça vaut, je pense que tu fais le bon choix.",0],["to be fair","pour être juste / honnêtement","To be fair, he did warn us.","Pour être juste, il nous avait prévenus.",0],["if you ask me","si tu veux mon avis","If you ask me, that deadline is unrealistic.","Si tu veux mon avis, cette deadline n'est pas réaliste.",0],["at the end of the day","en fin de compte","At the end of the day, it's your decision.","En fin de compte, c'est ta décision.",0],["truth be told","à vrai dire","Truth be told, I wasn't paying attention.","À vrai dire, je n'écoutais pas.",0],["for the record","pour info / que ce soit dit","For the record, I was against this from the start.","Pour info, j'étais contre depuis le début.",0]],"free":1},{"e":"⏳","t":"Adverbial phrases — Temps","s":4,"g":{"t":"every now and then vs once in a while","tip":"Les deux veulent dire « de temps en temps » et sont interchangeables à l'oral. Attention à la forme figée : every now and THEN, once IN a while.","q":[["I ___ go for a run in the morning.",["every now and then","every now and again then","now and every then"],0,"every now and then = de temps en temps"],["___, let's keep the current setup.",["For the time being","For the time","At the time being"],0,"for the time being = pour l'instant"]]},"w":[["for the time being","pour l'instant / en attendant","For the time being, let's stick with the current plan.","Pour l'instant, restons sur le plan actuel.",0],["in the meantime","en attendant / entre-temps","The fix won't be ready until Monday. In the meantime, use the workaround.","Le correctif ne sera pas prêt avant lundi. En attendant, utilise le contournement.",0],["sooner or later","tôt ou tard","Sooner or later, you'll have to tell her.","Tôt ou tard, tu devras lui dire.",0],["at some point","à un moment donné","At some point, we need to have that conversation.","À un moment donné, il faudra qu'on ait cette conversation.",0],["every now and then","de temps en temps","Every now and then, I still think about that trip.","De temps en temps, je repense encore à ce voyage.",0],["once in a while","de temps à autre","It's okay to treat yourself once in a while.","C'est OK de se faire plaisir de temps à autre.",0],["right off the bat","d'entrée de jeu","Right off the bat, I could tell something was wrong.","D'entrée de jeu, j'ai senti que quelque chose n'allait pas.",0],["as of now","à l'heure actuelle","As of now, we have no confirmation.","À l'heure actuelle, on n'a aucune confirmation.",0]],"free":1},{"e":"⚖️","t":"Adverbial phrases — Contraste","s":4,"g":{"t":"that being said vs having said that","tip":"Les deux introduisent une nuance après un constat, mais that being said est plus courant à l'oral. having said that est plus soutenu.","q":[["Great results. ___, there's room for improvement.",["That being said","That been said","That being say"],0,"that being said = cela dit"],["He's talented. ___, he needs to work on his attitude.",["Having said that","Having say that","Had said that"],0,"having said that = cela étant dit"]]},"w":[["that being said","cela dit","That being said, I still think we should try.","Cela dit, je pense quand même qu'on devrait essayer.",0],["having said that","cela étant dit","Having said that, I understand your concerns.","Cela étant dit, je comprends tes inquiétudes.",0],["regardless","quoi qu'il en soit / peu importe","Regardless, we need to meet the deadline.","Quoi qu'il en soit, on doit tenir la deadline.",0],["all the same","quand même / malgré tout","It's risky, but I want to try all the same.","C'est risqué, mais je veux quand même essayer.",0],["for all I know","si ça se trouve / pour ce que j'en sais","For all I know, he could be lying.","Si ça se trouve, il ment.",0],["be that as it may","quoi qu'il en soit (soutenu)","Be that as it may, we still have a contract.","Quoi qu'il en soit, on a quand même un contrat.",0],["then again","mais d'un autre côté","It's expensive. Then again, you get what you pay for.","C'est cher. Mais d'un autre côté, on a ce qu'on paie.",0],["either way","dans les deux cas / de toute façon","Either way, I'm fine with it.","Dans les deux cas, ça me va.",0]],"free":1},{"e":"🔗","t":"Adverbial phrases — Cause & conséquence","s":4,"g":{"t":"as a result vs as a consequence","tip":"as a result est neutre et très courant. as a consequence sonne plus formel et implique souvent un résultat négatif.","q":[["He missed three meetings. ___, he was fired.",["As a result","As a cause","As result"],0,"as a result = en conséquence"],["I didn't study. ___, I need a miracle.",["Needless to say","Needless to mention","Needless saying"],0,"needless to say = inutile de dire"]]},"w":[["as a result","en conséquence / du coup","We cut the budget. As a result, two projects were paused.","On a réduit le budget. Du coup, deux projets ont été suspendus.",0],["for some reason","pour une raison quelconque / va savoir pourquoi","For some reason, my internet went down.","Va savoir pourquoi, mon internet a coupé.",0],["needless to say","inutile de dire / évidemment","Needless to say, he wasn't invited back.","Inutile de dire qu'il n'a pas été réinvité.",0],["on account of","en raison de","The game was postponed on account of rain.","Le match a été reporté en raison de la pluie.",0],["with that in mind","dans cette optique","With that in mind, let's revise the timeline.","Dans cette optique, revoyons le planning.",0],["for that matter","d'ailleurs / du reste","I don't like the plan — or the budget, for that matter.","Je n'aime pas le plan — ni le budget, d'ailleurs.",0],["in that case","dans ce cas","In that case, let's postpone the meeting.","Dans ce cas, reportons la réunion.",0],["as it turns out","il s'avère que / en fait","As it turns out, she was right all along.","Il s'avère qu'elle avait raison depuis le début.",0]],"free":1}]};
